CREATE TABLE IF NOT EXISTS inv_stock_ledger (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, item_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NOT NULL, quantity_change DECIMAL(18,3) NOT NULL, transaction_type VARCHAR(30) NOT NULL, reference_type VARCHAR(40) NULL, reference_id INT UNSIGNED NULL, transaction_date DATE NOT NULL, note VARCHAR(255) NULL, created_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, KEY ix_inv_stock_scope(item_id,branch_id,transaction_date), CONSTRAINT fk_inv_stock_item FOREIGN KEY(item_id) REFERENCES md_items(id) ON DELETE RESTRICT, CONSTRAINT fk_inv_stock_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT);